#pragma once

#include "common.h"

#include <algorithm>
#include <cstddef>

//
// token list helpers
//

// length of the longest common prefix of two token lists
inline size_t get_common_prefix(const llama_tokens & a, const llama_tokens & b) {
    const size_t max_idx = std::min(a.size(), b.size());

    for (size_t i = 0; i < max_idx; ++i) {
        if (a[i] == b[i]) {
            continue;
        }

        return i;
    }

    return max_idx; // all tokens are equal
}

// length of the longest common suffix of two token lists
inline size_t get_common_suffix(const llama_tokens & a, const llama_tokens & b) {
    const size_t max_idx = std::min(a.size(), b.size());

    for (size_t i = 0; i < max_idx; ++i) {
        const llama_token ai = a[a.size() - 1 - i];
        const llama_token bi = b[b.size() - 1 - i];

        if (ai == bi) {
            continue;
        }

        return i;
    }

    return max_idx; // all tokens are equal
}

// number of occurrences of tok in tokens
inline size_t count(const llama_tokens & tokens, llama_token tok) {
    size_t n = 0;
    for (const auto & t : tokens) {
        if (t == tok) {
            ++n;
        }
    }
    return n;
}

// index of the first occurrence of tok in tokens, or npos if not found
inline size_t find(const llama_tokens & tokens, llama_token tok) {
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (tokens[i] == tok) {
            return i;
        }
    }
    return static_cast<size_t>(-1);
}

// true if tokens contains tok
inline bool contains(const llama_tokens & tokens, llama_token tok) {
    return find(tokens, tok) != static_cast<size_t>(-1);
}
