    // different lengths: b is a prefix of a
    assert(lcp_similarity(d, c) == 3.0f / 3.0f);
}

int main() {
    test_empty();
    test_identical();
    test_partial_match();
    test_different_lengths();
    test_lcp_similarity();

    return 0;
}

